const i={name:"Frequency Dominion",shortName:"Frequency Dominion Course",price:97,compareAt:997,tagline:"The 21-day radio campaign operating system for independent artists who refuse to stay unheard."},o=[{id:"m1",n:"01",title:"Command Identity",promise:"Stop sounding like a fan. Start sounding like a station's problem-solver.",lessons:[{id:"m1l1",title:"The unheard tax",minutes:8,outcome:"Name the exact cost of another ignored release cycle.",script:"You do not have a talent problem. You have a distribution identity problem. Radio directors do not owe you a listen. They owe their audience a show that does not suck. Frequency Dominion starts here: you are not begging for spins. You are offering a local, genre-fit, time-stamped solution. Write one sentence: 'I am the [genre] artist [city] stations use when they need [specific listener feeling].' That sentence is your north star for every email, voicemail, and follow-up in this course.",drill:"Write the identity sentence. Pin it above your send list. Do not pitch until it is specific enough to insult a generic artist."},{id:"m1l2",title:"Station as customer",minutes:11,outcome:"Map what a music director actually buys with a spin.",script:"A spin is inventory. Inventory has constraints: clock, format, legal ID, imaging, localism, and ego. Your track is a SKU. If the SKU does not fit the clock, it dies. In this lesson you list five constraints for your first target format (college, community, specialty, or commercial). You will never again send a 7-minute progressive suite to a 3:30 CHR clock and call it 'the industry is unfair.'",drill:"Pick one format. Write five constraints. Cut or edit one song to fit the tightest clock.",template:`Format: ____
Clock max: ____
Localism hook: ____
Competing current: ____
Why this week: ____`},{id:"m1l3",title:"Proof before volume",minutes:9,outcome:"Assemble a 4-line credibility stack that does not lie.",script:"Directors delete bios. They keep proof. Proof is: local show date, previous add, playlist, press quote, or a named champion at another station. Stack four lines. If you have none, manufacture ethical proof this week: one hometown gig, one college paper, one community station interview. Dominion is earned in public, then leveraged in the inbox.",drill:"Write a 4-line proof stack. If a line is empty, schedule the action that fills it in 7 days."},{id:"m1l4",title:"The no-spam oath",minutes:6,outcome:"Commit to targeted, named, human outreach only.",script:"18,000 contacts is a weapon. Weapons require discipline. You will never BCC a market. You will never use merge fields that say 'Hi there.' You will never send the same paragraph to college jazz and country morning drive. Break this oath and you burn the well for every independent artist behind you — including future you.",drill:"Write the oath on paper. Screenshot it. First campaign = 20 named contacts, not 2,000."}]},{id:"m2",n:"02",title:"Target Architecture",promise:"Build a city-by-city ladder so every send has a reason.",lessons:[{id:"m2l1",title:"Hometown heat map",minutes:14,outcome:"Extract every relevant station within 90 minutes of home.",script:"Open the RadioReach Vault. Filter your metro, then adjacent cities on your commute. Highlight music directors and specialty hosts first, then program directors, then general station lines last. Hometown is not 'cute.' Hometown is the only market where you are not a stranger. Directors champion locals because locals make the station feel planted. You start here or you start cold.",drill:"Export 25 hometown contacts. Rank A/B/C by format fit. A-list gets personalized audio this week."},{id:"m2l2",title:"Tour-route pre-roll",minutes:12,outcome:"Time pitches 21 days before every date on the calendar.",script:"A show without radio is a secret. Radio without a show is a rumor. Stack them. For each tour city, pull stations 21 days out. Subject line references the venue and date. Body offers an interview window the afternoon of load-in. This is how regional acts look national before they are.",drill:"If you have no tour, invent a 4-city weekend run and build the 21-day calendar anyway.",template:"City | Date | Station | Contact | Send day (D-21) | Interview offer | Follow-up D-10 | Follow-up D-3"},{id:"m2l3",title:"Format fit scoring",minutes:10,outcome:"Score every station 0–5 so you stop wasting A-game emails on D-fit rooms.",script:"Score: genre match (0–2), locality (0–1), named human (0–1), recent independent adds (0–1). Total 4–5 = send this week. 2–3 = nurture list. 0–1 = do not touch. Volume without scoring is how you train yourself that 'radio doesn't work.'",drill:"Score your 25 hometown contacts. Only 4–5s get Lesson 3.1 scripts."},{id:"m2l4",title:"The 20-station war room",minutes:8,outcome:"Lock a 21-day list you can actually work.",script:"Twenty stations. Not two hundred. Dominion is concentration. Print the list. Put it on the wall. Each name gets a status: queued, sent, opened, replied, added, dead. You update it daily like a chart. If you cannot manage twenty, you cannot manage a career.",drill:"Create the war-room table. Share it with one accountability human."}]},{id:"m3",n:"03",title:"The Pitch Weapon",promise:"Emails that survive 1.4 seconds of a music director's thumb.",lessons:[{id:"m3l1",title:"Subject lines that get opened",minutes:13,outcome:"Build 11 subject lines from the local-artist swipe logic.",script:"Subject lines that die: 'New single for your consideration.' Subject lines that live: 'Local [genre] for [show name] — 2:58, [city] date [month].' Specificity is respect. You prove you know the show. You prove the clock. You prove you are not a blast. Write eleven. Kill eight. Keep three. A/B them across your A-list only.",drill:"Write 11. Circle 3. Never reuse a loser on the same contact.",template:`1. [City] [genre] for [show] — [runtime]
2. Interview window [date] + track
3. Follow-up: still a fit for [show]?`},{id:"m3l2",title:"The 90-word pitch",minutes:16,outcome:"Write a pitch a director can finish before the kettle boils.",script:"Structure: (1) their name, (2) why this show this week, (3) one-sentence song, (4) runtime and one proof line, (5) one streaming link, (6) one ask (spin, interview, or feedback — never all three). Ninety words. If you cannot say it in ninety, you do not know what the song is for.",drill:"Write the 90-word pitch. Read it out loud. Cut until it is under 90."},{id:"m3l3",title:"EPK that does not embarrass you",minutes:11,outcome:"One page: photo, bio 80 words, links, one-sheet facts.",script:"Directors do not want your life story. They want: who, where, what it sounds like, where to play it, who already did. One page PDF or a clean link. No WeTransfer dumps. No 14-page press kits. Cover art that does not look like a default font. If the art is weak, fix art before you scale sends.",drill:"Build the one-pager. Have a civilian read it in 20 seconds and tell you the genre."},{id:"m3l4",title:"Audio assets for radio",minutes:10,outcome:"Deliver radio-ready files, not a Bandcamp shrug.",script:"WAV or high-bitrate MP3, clean metadata, no 2 minutes of silence, no unmastered bounce named finalFINAL3. Include a 30-second hook clip for imaging. Label files: Artist_Song_RadioEdit. If you cannot be found in a folder, you will not be found on the clock.",drill:"Export radio edit + 30s clip with correct metadata today."}]},{id:"m4",n:"04",title:"The 21-Day Campaign",promise:"A calendar that tells you who to email on which day.",lessons:[{id:"m4l1",title:"Week 0: load the war room",minutes:9,outcome:"Contacts scored, assets ready, send blocks booked.",script:"Before day 1 you do not send. You load. Vault filtered. Scores done. Pitch frozen. Calendar blocks: 45 minutes, four days a week. Campaigns fail in the gaps between 'I'll do it later.' Dominion is a calendar object.",drill:"Put four 45-minute blocks on the next 21 days. Non-negotiable."},{id:"m4l2",title:"Days 1–7: first blood sends",minutes:12,outcome:"Send 20 A-list emails. Log every one.",script:"Ten on day 1, ten on day 3. Personal first lines only. Log station, name, subject, time. If you cannot log it, it did not happen. Expect silence. Silence is data, not rejection. You are buying the right to follow up.",drill:"Send 10 today. Screenshot the log."},{id:"m4l3",title:"Days 8–14: the 3-touch follow-up",minutes:12,outcome:"Run the cadence that doubled replies in Accelerator tests.",script:"Touch 2 (day 8–10): one sentence + the 30s clip. Touch 3 (day 14): new information only — a show date, a quote, a different edit. Never 'just bumping this.' Never guilt. If they say no, thank them and leave the door unburned.",drill:"Write Touch 2 and Touch 3 now so you are not improvising under anxiety.",template:`Touch 2: [Name] — 30s hook if easier: [link]. Still a fit for [show]?
Touch 3: New: [show date / quote / edit]. Happy to drop it if not a fit.`},{id:"m4l4",title:"Days 15–21: adds, interviews, next market",minutes:10,outcome:"Convert replies into calendar facts and climb the ladder.",script:"A reply is not a win until it is a spin, an interview, or a clear no. Confirm add dates. Send thank-you same day. Screenshot the spin if it airs. That screenshot becomes proof for Module 1's next cycle and for the next city on the ladder. Then clone the war room for market two.",drill:"Draft the thank-you. Draft the market-two list of 15 stations."}]},{id:"m5",n:"05",title:"Human Frequency",promise:"Calls, interviews, and relationships that survive one song.",lessons:[{id:"m5l1",title:"When to pick up the phone",minutes:8,outcome:"Call only after a warm email or a local show hook.",script:"Cold calls to music directors are how legends get you labeled a pest. Call when: they replied, you have a local date, or community radio publishes a request line. Script: 20 seconds. Name, one song, one ask, permission to send. Then shut up.",drill:"Record yourself doing the 20-second call. Cringe means it is honest. Do it anyway."},{id:"m5l2",title:"Interview that books the next spin",minutes:11,outcome:"Give radio a story, not a discography.",script:"Hosts need tape. Give them: origin of the song in one anecdote, a local tie, a listener call-to-action, and a clean 15-second pull-quote. End by asking what they need from you next month. You are auditioning for a recurring slot, not a one-night stand.",drill:"Write 5 interview answers under 40 seconds each."},{id:"m5l3",title:"Thank-you economy",minutes:7,outcome:"Make champions feel seen so they stay champions.",script:"Same-day thank you. Social tag if they allow it. Physical note if they added you. Never demand a playlist screenshot in public. Protect their reputation and they will protect your song.",drill:"Prepare a thank-you note template and a social post that credits the station first."},{id:"m5l4",title:"Repairing a burned well",minutes:8,outcome:"If you already spammed, this is the apology that can reopen a door.",script:"Own it in one line. No excuses. Offer a single relevant track and permission to ignore. Then wait 90 days. Dominion includes knowing when you are not welcome yet.",drill:"If you have a burned contact, write the apology. Send only if it is true."}]},{id:"m6",n:"06",title:"Empire Loop",promise:"Turn one add into a machine: proof, income, next release.",lessons:[{id:"m6l1",title:"Proof compounding",minutes:9,outcome:"Every add becomes a line in the next pitch.",script:"Keep a proof ledger: station, date, show, quote. This is how Ohio gets Unearthed and how Unearthed gets the next coastal specialty show. Without a ledger you restart from zero every single.",drill:"Create the ledger. Enter any past win, even a campus show."},{id:"m6l2",title:"Airplay to income",minutes:12,outcome:"Route credibility into gigs, sync, and freelance.",script:"Radio is not a paycheck. Radio is a badge. Use the badge: pitch venues with 'now spinning on X,' pitch supervisors with regional story, pitch Upwork clients with proof you understand markets. The Vault opened the door. Frequency Dominion teaches you to walk through it with a rate.",drill:"Write one venue email and one client email that cite a specific station."},{id:"m6l3",title:"Release calendar as a radio calendar",minutes:10,outcome:"Never drop a single without a 21-day radio plan attached.",script:"Add date thinking: radio wants lead time. Work backwards from release: war room at T-28, first sends T-21, follow-ups T-14 and T-7, thank-yous T+2. If you cannot staff that, delay the drop. Amateur calendars create amateur careers.",drill:"Map your next release onto the T-28 skeleton."},{id:"m6l4",title:"The 90-day dominion review",minutes:8,outcome:"Audit sends, replies, adds, and kill what does not convert.",script:"Metrics that matter: sends, personalization rate, replies, adds, interviews, burned contacts. Vanity: total emails. Kill formats under 2% reply after 40 sends. Double down on the format that answered. This is how lists become empires.",drill:"Schedule the 90-day review on your calendar now."}]}],n=[{id:"wb1",title:"Identity Sentence Worksheet",blurb:"One line that makes a director understand why you exist."},{id:"wb2",title:"20-Station War Room (printable)",blurb:"A/B/C scores, send dates, status, next touch."},{id:"wb3",title:"90-Word Pitch Builder",blurb:"Six blocks, ninety words, one ask."},{id:"wb4",title:"21-Day Campaign Calendar",blurb:"Who to email on which day from T-21 to T+2."},{id:"wb5",title:"Proof Ledger",blurb:"Adds, quotes, interviews — compounding receipts."}],a=["Drop your identity sentence. If it could fit any artist, rewrite it.","Post a redacted 90-word pitch. We roast length, not your soul.","Share one hometown A-list station and why it scored 4+.","Week 2: paste Touch 2. Did you add new information or just bump?","Win thread: one add, one quote, one thank-you. Proof or it did not happen."];function s(){return o.flatMap(e=>e.lessons.map(t=>({...t,moduleId:e.id,moduleTitle:e.title})))}export{i as C,o as M,n as W,s as a,a as b};
